const payload = $input.first().json.body || $input.first().json;
if (!payload || typeof payload !== 'object') throw new Error('Invalid risk alert payload.');
const severity = String(payload.severity || '').toUpperCase();
if (!['LOW', 'MODERATE', 'HIGH', 'CRITICAL'].includes(severity)) throw new Error('severity must be LOW, MODERATE, HIGH, or CRITICAL.');
const riskScore = Number(payload.riskScore);
if (!Number.isFinite(riskScore) || riskScore < 0 || riskScore > 100) throw new Error('riskScore must be a number from 0 to 100.');
if (!payload.area || typeof payload.area !== 'object') throw new Error('area is required.');
if (!payload.commander || typeof payload.commander !== 'object') throw new Error('commander is required.');
return [{ json: { riskForecast: payload.riskForecast || {}, area: payload.area, severity, riskScore, commander: payload.commander, timestamp: payload.timestamp || new Date().toISOString(), simulationMode: payload.simulationMode === true, validatedAt: new Date().toISOString() } }];

const data = $input.first().json;
const isHighOrCritical = data.severity === 'HIGH' || data.severity === 'CRITICAL';
const isCritical = data.severity === 'CRITICAL';
return [{ json: { ...data, evaluation: { isHighOrCritical, isCritical, requiresCommanderReview: isCritical, emergencyExecutionStatus: isCritical ? 'AWAITING_COMMANDER_APPROVAL' : 'NOT_APPLICABLE', humanApprovalPolicy: 'Emergency execution requires commander approval before simulated execution.' } } }];

const data = $input.first().json;
const alertId = `ALT-RISK-${Date.now().toString(36).toUpperCase()}`;
return [{ json: { ...data, alertId, alertLog: { alertId, timestamp: data.timestamp, loggedAt: new Date().toISOString(), area: data.area, severity: data.severity, riskScore: data.riskScore, commander: data.commander, status: 'PENDING_EMAIL_DISPATCH', requiresCommanderReview: data.evaluation.requiresCommanderReview, emergencyExecutionStatus: data.evaluation.emergencyExecutionStatus } } }];
